SELECT DATE_TRUNC('MONTH', usage_events.start_time) AS "month", COUNT(usage_events.event_id) AS "event_count_count" FROM usage_events INNER JOIN customers ON LPAD(CAST(customers.cust_id AS VARCHAR), 10, '0') = usage_events.client_no WHERE start_time >= CAST('2026-06-01 00:00:00' AS TIMESTAMP) AND start_time < CAST('2026-11-01 00:00:00' AS TIMESTAMP) AND customers.status = 'A' GROUP BY DATE_TRUNC('MONTH', usage_events.start_time) LIMIT 50